// личных данных → экран открытия. Коммент программиста (4bc943d): под «התנתקות» — «מחיקת חשבון» → окно со списком данных.
// Факт 21.10: кнопка «מחיקת חשבון» под «התנתקות»; окно «למחוק את החשבון?» со списком (פרטים והעדפות, תמונת הפרופיל, היסטוריית התפילות
// והרצף, ההישגים, התאריכים החשובים, התזכורות והאנשים במפת ההשפעה, «אי אפשר לשחזר», «תוכלו להירשם מחדש»), «ביטול» / «מחיקה לצמיתות»
// (2110-b7295677-dialog.png). Само удаление проверил пользователь вручную на одноразовом аккаунте «QA reg 2110» — аккаунт удалился.
// АВТОТЕСТ НЕ УДАЛЯЕТ АККАУНТ: нажимается только «ביטול» (по точному имени кнопки). «מחיקה לצמיתות» не нажимается никогда.
// Удаление + повторная регистрация тем же номером — ВРУЧНУЮ, только на одноразовом тестовом аккаунте (кейс PR-06, шаги «Вручную»).
// Кейс: .qa/tests/profile/PR-06-delete-account.md.
import { expect } from '@wdio/globals';
import { byText, byTextContains, scrollToText } from '../../helpers/ui.ts';
import { shown } from '../_lib/app-0710.ts';
import { goHome, openProfile, button, nodes } from '../_lib/readiness-1910.ts';
import { DELETE_ACCOUNT_BTN, DELETE_ACCOUNT_TITLE, DELETE_ACCOUNT_BODY, DELETE_ACCOUNT_CONFIRM, saveShot } from '../_lib/app-2110.ts';

describe('21.10 — удаление аккаунта: кнопка и окно (#a7caf6)', () => {
  afterEach(async () => {
    // Окно не должно остаться открытым: только «ביטול».
    if (await shown(byText(DELETE_ACCOUNT_TITLE))) await (await button('ביטול')).click().catch(() => {});
    await goHome().catch(() => {});
  });

  it('PR-06 Профиль: «מחיקת חשבון» под «התנתקות» → окно «למחוק את החשבון?» со списком удаляемых данных и «ביטול» / «מחיקה לצמיתות»; «ביטול» закрывает окно, аккаунт и профиль на месте #a7caf6 #b7295677 Apple 5.1.1(v) @prod-safe', async () => {
    await openProfile();
    const before = (await nodes()).map((n) => n.label).filter((l) => /^(טלפון|אימייל|שם)/.test(l)).join(' | ');
    await scrollToText('התנתקות');
    await scrollToText(DELETE_ACCOUNT_BTN);
    const ns = await nodes();
    const logout = ns.find((n) => n.label === 'התנתקות');
    const del = ns.find((n) => n.label === DELETE_ACCOUNT_BTN);
    expect(logout && del).toBeTruthy();
    expect(del!.y).toBeGreaterThan(logout!.y);                  // под «התנתקות»

    await (await button(DELETE_ACCOUNT_BTN)).click();
    await (await byText(DELETE_ACCOUNT_TITLE)).waitForExist({ timeout: 10000 });
    const text = (await nodes()).map((n) => n.label).join('\n');
    for (const part of DELETE_ACCOUNT_BODY) expect(text).toContain(part);
    expect(await (await button('ביטול')).isExisting()).toBe(true);
    expect(await (await button(DELETE_ACCOUNT_CONFIRM)).isExisting()).toBe(true);
    console.log(`[PR-06] окно: ${await saveShot('PR-06-delete-dialog.png')} (RTL текста — сверить по скрину)`);

    await (await button('ביטול')).click();                       // ТОЛЬКО «ביטול»
    await expect(byText(DELETE_ACCOUNT_TITLE)).not.toBeExisting({ wait: 10000 });
    await expect(byText('פרופיל אישי')).toBeExisting();
    await expect(byTextContains(DELETE_ACCOUNT_BTN)).toBeExisting();
    await openProfile();
    const after = (await nodes()).map((n) => n.label).filter((l) => /^(טלפון|אימייל|שם)/.test(l)).join(' | ');
    expect(after).toBe(before);
  });
});
